/**
 * 客户端网络传输类
 */
var net = require("net");
var dgram = require("dgram");
var Endpoint = require("@taf/taf-utils").Endpoint;
var NetworkBuffer = require("../util/NetworkBuffer").NetworkBuffer;
var ProtoMessage = require('../util/ProtoMessage').ProtoMessage;

const feed = function (stream, networkBuffer, transceiver) {

    try {
        while (networkBuffer.getBufferLength() > 0) {

            var message = new ProtoMessage();

            if (stream.feed(networkBuffer, message)) {

                transceiver._socket.emit("message", message);
            } else {
                break;
            }

        }
    } catch (e) {
        console.log(`feed exception`, transceiver._connectStr, e);
        transceiver._socket.emit("error", e);
        return false;
    }

    return true;
}

/////////////////////////////////////////////////////////////////////////////////
var Transceiver = function () {

};
Transceiver.ES_UNCONNECTED = 1; //没有连接
Transceiver.ES_CONNECTING = 2; //正在连接中
Transceiver.ES_CONNECTED = 3; //已经连接上

/////////////////////////////////////////////TCP协议套接口类////////////////////////////////////////////////////////////
var TCPTransceiver = function ($adapter, $endpoint) {
    this._adapter = $adapter;
    this._endpoint = $endpoint;

    this._stream = undefined; //协议解析器的实例
    this._socket = undefined;
    this._status = Transceiver.ES_UNCONNECTED;
    this._localEndpoint = undefined;
    this._socket_evt = undefined;
    this._connectStr = "servant=" + this._adapter._worker._objname + ",endpoint=" + this._endpoint.toString(); //连接信息

    this._networkBuffer = NetworkBuffer.New();
};
module.exports.TCPTransceiver = TCPTransceiver;

//定义TCP接口的属性
//当socket存在，并且处于已连接状态时，才去获取本地端口
TCPTransceiver.prototype.__defineGetter__("LocalEndpoint", function () {
    if (this._localEndpoint === undefined && this._socket && this._status == Transceiver.ES_CONNECTED) {
        this._localEndpoint = new Endpoint();
        this._localEndpoint.sProtocol = "tcp";
        this._localEndpoint.sHost = this._socket.localAddress;
        this._localEndpoint.iPort = this._socket.localPort;
    }

    return this._localEndpoint;
});

//重新连接
TCPTransceiver.prototype.reconnect = function () {
    var self = this;

    self._stream = new self._adapter._worker._protocol();
    //设置协议类型，feed的时候需要区分jce和wup编码
    self._stream._version = self._adapter._worker.version || 1;
    self._socket = new net.Socket();
    self._socket.setNoDelay(true);
    self._status = Transceiver.ES_CONNECTING;
    self._socket.connect(self._endpoint.iPort, self._endpoint.sHost);
    //console.log("reconnect " + self._connectStr)

    self._socket_evt = {
        connect: function () {
            //console.log("connected|" + self._connectStr)
            self._status = Transceiver.ES_CONNECTED;
            self._networkBuffer.clear();
            self._adapter.doInvoke();
            self._adapter.connExc = false;
        },
        close: function () {
            //console.log("connect close|" + self._connectStr)
            self.close();
            self._adapter._setInactive();
        },
        error: function () {
            //console.log("connect error|" + self._connectStr)
            self.close();
            self._adapter._setInactive();
            self._adapter.connExc = true;
        },
        data: function (data) {
            self._networkBuffer.addBuffer(data);
            if (!feed(self._stream, self._networkBuffer, self)) {
                //console.log("connect data error|" + self._connectStr)
                self.close();
            }
        }
    };

    self._socket.on("connect", self._socket_evt.connect);
    self._socket.on("data", self._socket_evt.data);
    self._socket.on("error", self._socket_evt.error);
    self._socket.on("close", self._socket_evt.close);
    self._socket.on("message", function ($protoMessage) {
        self._adapter.doResponse($protoMessage);
    });
};

//发送未经编码的请求
TCPTransceiver.prototype.sendRequest = function ($protoMessage, bForce) {
    if ($protoMessage && this._endpoint) {
        if (this._endpoint.setId) {
            $protoMessage.setId = this._endpoint.setId;
        }
    }

	//console.log(`tcp send|status=${this._status}|force=${bForce}|id=${$protoMessage.iRequestId}|func=${$protoMessage.sFuncName}|remote=${this._connectStr}|localaddr=${this._socket.localAddress}|localport=${this._socket.localPort}`)

    if (this._status === Transceiver.ES_CONNECTED || bForce) {
        if(this._socket && this._stream && !this._socket.destroyed){
            this._socket.write(this._stream.compose($protoMessage));
            return true;
        }
    }

    return false;
};

TCPTransceiver.prototype.hasConnected = function () {
    return (this._status === Transceiver.ES_CONNECTED) && this._socket && !this._socket.destroyed;
};
TCPTransceiver.prototype.isConnecting = function () {
    return (this._status === Transceiver.ES_CONNECTING) && this._socket && !this._socket.destroyed;
};
TCPTransceiver.prototype.isValid = function () {
    return (this._status !== Transceiver.ES_UNCONNECTED) && this._socket && !this._socket.destroyed;
};

//关闭当前网络套接字
TCPTransceiver.prototype.close = function () {
    this._status = Transceiver.ES_UNCONNECTED;
    this._stream = undefined;

    if (this._socket) {
        this._socket.removeListener("connect", this._socket_evt.connect);
        this._socket.removeListener("error", this._socket_evt.error);
        this._socket.removeListener("close", this._socket_evt.close);
        this._socket.removeListener("data", this._socket_evt.data);
        this._socket.destroy();
        this._socket = undefined;
    }

    //原来的地址已经失效，现在清空，下次调用接口时重新获取
    this._localEndpoint = undefined;
};

/////////////////////////////////////////////UDP协议套接口类////////////////////////////////////////////////////////////
var UDPTransceiver = function ($adapter, $endpoint) {
    this._adapter = $adapter;
    this._endpoint = $endpoint;
    this._stream = undefined;
    this._socket = undefined;
    this._status = Transceiver.ES_UNCONNECTED;
    this._localEndpoint = undefined;

    this._networkBuffer = NetworkBuffer.New();

};
module.exports.UDPTransceiver = UDPTransceiver;

UDPTransceiver.prototype.__defineGetter__("LocalEndpoint", function () {
    if (this._localEndpoint === undefined && this._socket && this._status == Transceiver.ES_CONNECTED) {
        this._localEndpoint = new Endpoint();
        this._localEndpoint.sProtocol = "udp";
        this._localEndpoint.sHost = this._socket.address().address;
        this._localEndpoint.iPort = this._socket.address().port;
    }

    return this._localEndpoint;
});

//启动传输
UDPTransceiver.prototype.reconnect = function () {
    var self = this;

    self._stream = new self._adapter._worker._protocol();
    //设置协议类型，feed的时候需要区分jce和wup编码
    self._stream._version = self._adapter._worker.version || 1;
    self._socket = dgram.createSocket("udp4");
    self._socket.on("message", function ($msg) {
        self._networkBuffer.clear();
        self._networkBuffer.addBuffer($msg);
        self._stream.feed(self._networkBuffer);
    });
    self._socket.on("message", function ($protoMessage) {
        self._adapter.doResponse($protoMessage);
    });
    self._status = Transceiver.ES_CONNECTED;
};

UDPTransceiver.prototype.sendRequest = function ($protoMessage) {
    if (this._status === Transceiver.ES_CONNECTED) {
        var NodeBuffer = this._stream.compose($protoMessage);
        this._socket && this._socket.send(NodeBuffer, 0, NodeBuffer.length, this._endpoint.iPort, this._endpoint.sHost);
        return true;
    }
    return false;
};

UDPTransceiver.prototype.hasConnected = function () {
    return this._status === Transceiver.ES_CONNECTED;
};
UDPTransceiver.prototype.isConnecting = function () {
    return this._status === Transceiver.ES_CONNECTING;
};
UDPTransceiver.prototype.isValid = function () {
    return this._status !== Transceiver.ES_UNCONNECTED;
};

//关闭当前网络套接字
UDPTransceiver.prototype.close = function () {
    this._status = Transceiver.ES_UNCONNECTED;
    this._stream = undefined;
    if (this._socket) {
        this._socket.close();
        this._socket = undefined;
    }
    //原来的地址已经失效，现在清空，下次调用接口时重新获取
    this._localEndpoint = undefined;
};
